import{_ as s,o,c as a,ao as t}from"./chunks/framework.D7TN4pt9.js";const g=JSON.parse('{"title":"Agent Sessions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/orchestrator.md","filePath":"guide/orchestrator.md","lastUpdated":null}'),n={name:"guide/orchestrator.md"};function r(i,e,d,l,h,c){return o(),a("div",null,[...e[0]||(e[0]=[t('<h1 id="Agent-Sessions" tabindex="-1">Agent Sessions <a class="header-anchor" href="#Agent-Sessions" aria-label="Permalink to &quot;Agent Sessions {#Agent-Sessions}&quot;">​</a></h1><p>An agent session is a Claude Code or Codex process running in a workspace on the <strong>backend daemon</strong>: you describe what you want in the agent pane, and it reads code, writes code, and runs code in the workspace&#39;s <a href="./repl">REPL</a> to get there. For the pane itself, see <a href="/ship-of-tools/stable/guide/interface#The-Agent-Pane">The agent pane</a>.</p><p>Creating, switching and watching sessions is in <a href="./agents">Running several agents</a>. This page covers the skills and permission flags.</p><h2 id="What-Ship-of-Tools-adds-to-the-agent" tabindex="-1">What Ship of Tools adds to the agent <a class="header-anchor" href="#What-Ship-of-Tools-adds-to-the-agent" aria-label="Permalink to &quot;What Ship of Tools adds to the agent {#What-Ship-of-Tools-adds-to-the-agent}&quot;">​</a></h2><p>The installer gives each agent CLI a set of skills and hooks (listed under <a href="/ship-of-tools/stable/start/install#install-footprint">What the installer changes</a>):</p><ul><li><p><strong>Skills</strong> that call small command-line tools: <code>julia-repl</code> runs code in the session&#39;s REPL (<a href="/ship-of-tools/stable/guide/repl#agents-repl">How agents use the REPL</a>), <code>show-result</code> puts a file in your preview pane or opens a page in your browser, and <code>sot-comm</code> sends messages to other sessions. Claude Code gets all of them; Codex gets only <code>sot-comm</code> and <code>sot-session-start</code>, so Codex sessions have no REPL skill yet.</p></li><li><p><strong>Hooks</strong> that report the session&#39;s work state (working, blocked, done), which is what colors its row. See <a href="./../concepts/work-state">Work-state colors</a>.</p></li></ul><h2 id="Permission-mode" tabindex="-1">Permission mode <a class="header-anchor" href="#Permission-mode" aria-label="Permalink to &quot;Permission mode {#Permission-mode}&quot;">​</a></h2><p>Sessions created from the window start their agent with:</p><ul><li><p><strong>Claude Code</strong>: <code>claude --permission-mode auto</code>.</p></li><li><p><strong>Codex</strong>: <code>codex --dangerously-bypass-approvals-and-sandbox --dangerously-bypass-hook-trust</code>, through the <code>ccx</code> launcher, which also marks the session&#39;s directory as trusted in <code>~/.codex/config.toml</code>.</p></li></ul><p>Claude Code&#39;s auto mode is not a bypass: a separate classifier model reviews each action before it runs. See Claude Code&#39;s <a href="https://code.claude.com/docs/en/permission-modes" target="_blank" rel="noreferrer">permission modes</a>. Codex has no equivalent reviewed mode here: its flags turn approvals and the sandbox off.</p><p>These permission flags are fixed: no setting or environment variable changes them. The Claude Code flags are built into the daemon, and the Codex flags are in the <code>ccx</code> script, which every update overwrites. Ship of Tools adds no permission tiers or action gating of its own on top.</p><h2 id="See-also" tabindex="-1">See also <a class="header-anchor" href="#See-also" aria-label="Permalink to &quot;See also {#See-also}&quot;">​</a></h2><ul><li><p><a href="./repl">The REPL</a> — the session the agent runs code in.</p></li><li><p><a href="./agents">Running several agents</a> — creating, switching and watching sessions.</p></li></ul>',13)])])}const u=s(n,[["render",r]]);export{g as __pageData,u as default};
